<script lang="ts">import type{CascaderOption}from'@fex-design/core/cascader/types';import{onDestroy}from'svelte';import{remoteRegionSearch}from'./data';import DemoCascader from'./demo-cascader.svelte';import Demo from'./demo-section.svelte';let options=$state<readonly CascaderOption[]>([]),loading=$state(false),timer:ReturnType<typeof setTimeout>|undefined,request=0;function search(keyword:string){if(timer)clearTimeout(timer);const id=++request;if(!keyword.trim()){loading=false;return}loading=true;timer=setTimeout(()=>{if(id!==request)return;options=remoteRegionSearch(keyword);loading=false},800)}onDestroy(()=>{request++;if(timer)clearTimeout(timer)})</script><Demo title="Remote search" description="Ancestor-preserving results ignore stale responses."><DemoCascader showSearch filterOption={false} {loading} {options} onSearch={search}/></Demo>
